# Qwen3-8B yes/no log-prob labelling of all training reports on 2xT4 (fp16, sharded).
import base64, glob, os, subprocess, sys
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "transformers>=4.51,<5", "accelerate"], check=False)
open("/kaggle/working/llm_label.py", "wb").write(base64.b64decode(""))
from huggingface_hub import snapshot_download
path = snapshot_download("Qwen/Qwen3-8B", local_dir="/kaggle/tmp/qwen3-8b",
                         allow_patterns=["*.json", "*.safetensors", "*.txt", "merges.txt"])
import pandas as pd
comp = [c for c in glob.glob("/kaggle/input/**/train.csv", recursive=True) if "rsna-knee" in c][0]
df = pd.read_csv(comp)
df = pd.concat([df[df.ACL.notna()], df[df.ACL.isna()]])  # gold first: early validation
df.to_csv("/kaggle/working/train_ordered.csv", index=False)
r = subprocess.run([sys.executable, "/kaggle/working/llm_label.py", "--cuda", "--model", path,
                    "--train-csv", "/kaggle/working/train_ordered.csv",
                    "--out", "/kaggle/working/qwen3_labels.csv"])
print("exit", r.returncode)
